#!/bin/bash
# fix_seo.sh — har page ka apna title, description, Open Graph, canonical,
# JSON-LD, aur sitemap.xml + robots.txt.
set -u
echo "=========================================="
echo " SEO"
echo "=========================================="

# share ki tasveer, script ke andar hi rakhi hui hai
base64 -d > /root/og-cover.jpg <<'IMGEOF'

IMGEOF
echo ">> og-cover.jpg: $(du -h /root/og-cover.jpg | cut -f1)"

cat > /root/_seo.py <<'PYEOF'
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
SEO for xpertcreation.com.

What this actually does, and what it does not:

  It gives every page its own title and description, an Open Graph and
  Twitter card so shared links show a picture instead of a bare URL, a
  canonical link so www and non-www are not counted as two pages, and
  JSON-LD so Google can read what each page is. It writes a sitemap and a
  robots.txt so nothing has to be found by luck.

  It does not make the site rank first. Nothing does, on its own. This is
  the part that makes the site legible to a search engine - what happens
  after that depends on the pages being useful and on people linking to
  them, over months.

Nothing is written unless every page it touches is found.
"""

import io, os, re, shutil, sys, time
from xml.sax.saxutils import escape as xesc

