NOINDEX = {"account.html", "chat.html", "moderate.html", "offline.html",
           "card_public.html"}


def head_block(path, title, desc, ld_type, indexable):
    url = SITE + (path if path != "/" else "/")
    ld = {
        "@context": "https://schema.org",
        "@type": ld_type,
        "name": title.split(" \u2014 ")[0],
        "url": url,
        "description": desc,
        "inLanguage": "en",
        "publisher": {"@type": "Organization", "name": "XpertCreation",
                      "url": SITE, "logo": SITE + "/brand/icon-512.png"},
    }
    if ld_type == "WebSite":
        ld["potentialAction"] = {
            "@type": "SearchAction",
            "target": SITE + "/tools?q={search_term_string}",
            "query-input": "required name=search_term_string",
        }
    if ld_type in ("WebApplication", "VideoGame"):
        ld["applicationCategory"] = "UtilitiesApplication"
        ld["operatingSystem"] = "Any"
        ld["offers"] = {"@type": "Offer", "price": "0", "priceCurrency": "USD"}

    import json
    out = []
    out.append('<meta name="description" content="%s">' % desc.replace('"', "&quot;"))
    out.append('<link rel="canonical" href="%s">' % url)
    if not indexable:
        out.append('<meta name="robots" content="noindex,follow">')
    else:
        out.append('<meta name="robots" content="index,follow,max-image-preview:large">')
    out.append('<meta property="og:type" content="website">')
    out.append('<meta property="og:site_name" content="XpertCreation">')
    out.append('<meta property="og:title" content="%s">' % title.replace('"', "&quot;"))
    out.append('<meta property="og:description" content="%s">' % desc.replace('"', "&quot;"))
    out.append('<meta property="og:url" content="%s">' % url)
    out.append('<meta property="og:image" content="%s">' % OG_URL)
    out.append('<meta property="og:image:width" content="1200">')
    out.append('<meta property="og:image:height" content="630">')
    out.append('<meta property="og:locale" content="en_US">')
    out.append('<meta name="twitter:card" content="summary_large_image">')
    out.append('<meta name="twitter:title" content="%s">' % title.replace('"', "&quot;"))
    out.append('<meta name="twitter:description" content="%s">' % desc.replace('"', "&quot;"))
    out.append('<meta name="twitter:image" content="%s">' % OG_URL)
    out.append('<script type="application/ld+json">%s</script>'
               % json.dumps(ld, ensure_ascii=False, separators=(",", ":")))
    return "\n".join(out)


MARK_OPEN = "<!-- seo:start -->"
MARK_CLOSE = "<!-- seo:end -->"


def patch_page(text, path, title, desc, ld_type, indexable):
    """Replace the title, and drop a marked block in the head. Run twice and
    the second run replaces the first block rather than stacking another."""
    if not re.search(r"<title>[\s\S]*?</title>", text):
        return None, "no <title>"

    text = re.sub(r"<title>[\s\S]*?</title>",
                  lambda m: "<title>%s</title>" % title, text, count=1)

    # drop any description we or anyone else left outside our block
    text = re.sub(r'\n?[ \t]*<meta\s+name="description"[^>]*>', "", text, count=0)

    block = MARK_OPEN + "\n" + head_block(path, title, desc, ld_type, indexable) + "\n" + MARK_CLOSE

    if MARK_OPEN in text:
        text = re.sub(re.escape(MARK_OPEN) + r"[\s\S]*?" + re.escape(MARK_CLOSE),
                      lambda m: block, text, count=1)
    else:
        text = text.replace("</title>", "</title>\n" + block, 1)
    return text, None


def build_sitemap():
    today = time.strftime("%Y-%m-%d")
    rows = []
    for path, f, title, desc, ld, in_map, pri in PAGES:
        if not in_map:
            continue
        rows.append(
            "  <url>\n"
            "    <loc>%s</loc>\n"
            "    <lastmod>%s</lastmod>\n"
            "    <changefreq>weekly</changefreq>\n"
            "    <priority>%s</priority>\n"
            "  </url>" % (xesc(SITE + path), today, pri))
    return ('<?xml version="1.0" encoding="UTF-8"?>\n'
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
            + "\n".join(rows) + "\n</urlset>\n")


ROBOTS = """User-agent: *
Allow: /

# Nothing useful to a search engine, and some of it is private.
Disallow: /account
Disallow: /login
Disallow: /register
Disallow: /chat
Disallow: /chat/
Disallow: /moderate
Disallow: /offline
Disallow: /api/
Disallow: /dl/

Sitemap: %s/sitemap.xml
""" % SITE


def main():
    if not os.path.isdir(LAND):
        print("MISSING: %s" % LAND); return 1

    missing = [f for _, f, _, _, _, _, _ in PAGES
               if not os.path.exists(os.path.join(LAND, f))]
    if missing:
        print("ABORTED - these pages are not there: %s" % ", ".join(missing))
        return 2

    print("SEO  (%s)" % ("DRY RUN" if DRY else "apply"))
    print("=" * 46)
    print("\n[1/4] %d pages" % len(PAGES))

    planned = []
    for path, f, title, desc, ld, in_map, pri in PAGES:
        p = os.path.join(LAND, f)
        s = io.open(p, encoding="utf-8").read()
        new, err = patch_page(s, path, title, desc, ld, f not in NOINDEX)
        if err:
            print("    !! %-18s %s" % (f, err)); return 3
        planned.append((p, f, new))
        print("    ok  %-18s %s" % (f, path))

    if DRY:
        print("\n[2/4] would write sitemap.xml (%d urls) and robots.txt"
              % sum(1 for x in PAGES if x[5]))
        print("[3/4] would copy %s -> brand/og-cover.jpg" % OG_SRC)
        print("\nDry run complete. No files touched.")
        return 0

    print("\n[2/4] writing pages")
    for p, f, new in planned:
        shutil.copy2(p, "%s.bakseo_%s" % (p, STAMP))
        io.open(p, "w", encoding="utf-8").write(new)
    print("    ok  %d pages written, each with a .bakseo_%s beside it"
          % (len(planned), STAMP))

    print("\n[3/4] sitemap and robots")
    io.open(os.path.join(LAND, "sitemap.xml"), "w", encoding="utf-8").write(build_sitemap())
    io.open(os.path.join(LAND, "robots.txt"), "w", encoding="utf-8").write(ROBOTS)
    print("    ok  sitemap.xml  (%d urls)" % sum(1 for x in PAGES if x[5]))
    print("    ok  robots.txt")

    print("\n[4/4] share image")
    if os.path.exists(OG_SRC):
        dest = os.path.join(LAND, "brand", "og-cover.jpg")
        if not os.path.isdir(os.path.dirname(dest)):
            os.makedirs(os.path.dirname(dest))
        shutil.copy2(OG_SRC, dest)
        print("    ok  brand/og-cover.jpg")
    else:
        print("    !! %s not found - og:image will 404 until it is there" % OG_SRC)

    # checks
    print("\nverify:")
    ok = True
    import xml.dom.minidom
    try:
        xml.dom.minidom.parse(os.path.join(LAND, "sitemap.xml"))
        print("    ok  sitemap.xml is valid xml")
    except Exception as e:
        ok = False; print("    !! sitemap.xml: %s" % e)

    import json
    for path, f, title, desc, ld, in_map, pri in PAGES:
        s = io.open(os.path.join(LAND, f), encoding="utf-8").read()
        m = re.search(r'<script type="application/ld\+json">([\s\S]*?)</script>', s)
        if not m:
            ok = False; print("    !! %s has no JSON-LD" % f); continue
        try:
            json.loads(m.group(1))
        except Exception as e:
            ok = False; print("    !! %s JSON-LD broken: %s" % (f, e))
        if s.count(MARK_OPEN) != 1:
            ok = False; print("    !! %s has %d seo blocks" % (f, s.count(MARK_OPEN)))
        if s.count('name="description"') != 1:
            ok = False; print("    !! %s has %d descriptions"
                              % (f, s.count('name="description"')))
    if ok:
        print("    ok  every page has one seo block, one description, valid JSON-LD")

    print("\n%s" % ("DONE - purge Cloudflare cache." if ok else "DONE WITH WARNINGS."))
    return 0 if ok else 3


if __name__ == "__main__":
    sys.exit(main())

PYEOF

